@@ -1,11 +1,46 @@
 export type LatLng = { lat: number; lng: number };
+
+const EARTH_RADIUS_KM = 6371.0088;
+
+function assertValidPoint(point: LatLng, label: string): void {
+  const { lat, lng } = point;
+  if (
+    !Number.isFinite(lat) ||
+    !Number.isFinite(lng) ||
+    lat < -90 ||
+    lat > 90 ||
+    lng < -180 ||
+    lng > 180
+  ) {
+    throw new RangeError(
+      `${label} has invalid coordinates: { lat: ${lat}, lng: ${lng} }`,
+    );
+  }
+}

 /** Great-circle distance in kilometres. */
 export function haversineKm(a: LatLng, b: LatLng): number {
-  throw new Error("not implemented");
+  assertValidPoint(a, "first point");
+  assertValidPoint(b, "second point");
+  const toRad = (deg: number) => (deg * Math.PI) / 180;
+  const sinHalfLat = Math.sin(toRad(b.lat - a.lat) / 2);
+  const sinHalfLng = Math.sin(toRad(b.lng - a.lng) / 2);
+  const h =
+    sinHalfLat * sinHalfLat +
+    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * sinHalfLng * sinHalfLng;
+  return 2 * EARTH_RADIUS_KM * Math.asin(Math.min(1, Math.sqrt(h)));
 }

